/*
 * A090298  Permutation of natural numbers generated by 5-row array shown
 *          below.
 * https://oeis.org/A090298
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn
 * Formula:   not stated
 * Range:     u8 n <= 72, u16 n <= 72, u32 n <= 72, u64 n <= 72, u128 n <= 72,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Permutation of natural numbers generated by a 5-row array.  
   The array is read along anti‑diagonals (i+j = constant) where each
   row r (1 ≤ r ≤ 5) contains the arithmetic progression
      odd j : base_odd[r]  + 10 * ((j-1)/2)
      even j: base_even[r] + 10 * ((j-2)/2)

   The sequence a(n) is the n-th element in this diagonal order.  */

#include <stdint.h>

seq_t a(idx_t n)
{
    /* Locate the anti‑diagonal S = i + j that contains the n-th term */
    idx_t S = 2;          /* smallest possible sum (row 1 + column 1) */
    idx_t cum = 0;        /* cumulative number of terms before this diagonal */

    while (1) {
        idx_t count = S - 1;        /* number of rows that participate (≤ 5) */
        if (count > 5) count = 5;
        if (cum + count >= n) break;
        cum += count;
        ++S;
    }

    /* Index inside the current diagonal (0‑based) */
    idx_t offset = n - cum - 1;
    idx_t row   = offset + 1;   /* 1‑based row index */
    idx_t j     = S - row;      /* column index (also 1‑based) */

    /* Base values for each row at first odd and first even column */
    static const seq_t base_odd  [5] = {1, 2, 3, 4, 5};
    static const seq_t base_even [5] = {9, 8, 7, 6, 10};

    if (j & 1) {   /* odd column */
        seq_t val = base_odd[row-1] +
                    (seq_t)10 * (seq_t)((j-1)/2);
        return val;
    } else {       /* even column */
        seq_t val = base_even[row-1] +
                    (seq_t)10 * (seq_t)((j-2)/2);
        return val;
    }
}
